package main

import (
	"crypto/subtle"
	"flag"
	"fmt"
	"net"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	"github.com/mark3labs/mcp-go/server"
	mcptools "github.com/mvanhorn/printing-press-library/library/marketing/screencloud/internal/mcp"
)

// Transport selection order: --transport flag, then PP_MCP_TRANSPORT env,
// then the first transport declared in the spec (see MCPConfig.Transport).
// The flag surface lets one binary serve stdio locally and streamable HTTP
// when hosted in a container or remote sandbox, matching the Anthropic
// guidance that production agents need a remote option.

const (
	defaultHTTPAddr = "127.0.0.1:7777"
)

// version is the printed MCP server's version, overridable at build time via ldflags.
var version = "0.0.0-dev"

func main() {
	// Pin the learn-event surface for this process and every walker
	// shell-out child, so usage events record surface=mcp.
	_ = os.Setenv("SCREENCLOUD_LEARN_SURFACE", "mcp")
	s := server.NewMCPServer(
		"Screencloud",
		version,
		server.WithToolCapabilities(false),
	)

	mcptools.RegisterTools(s)

	transport := flag.String("transport", defaultTransport(), "MCP transport: stdio | http")
	addr := flag.String("addr", defaultHTTPAddr, "bind address for http transport (host:port or :port)")
	flag.Parse()

	switch strings.ToLower(*transport) {
	case "stdio":
		if err := server.ServeStdio(s); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	case "http":
		host, _, err := net.SplitHostPort(*addr)
		if err != nil {
			fmt.Fprintf(os.Stderr, "invalid --addr %q: %v\n", *addr, err)
			os.Exit(2)
		}
		ip := net.ParseIP(host)
		if host != "localhost" && (ip == nil || !ip.IsLoopback()) {
			fmt.Fprintln(os.Stderr, "refusing non-loopback MCP HTTP bind without an authenticated TLS reverse proxy; bind 127.0.0.1 and proxy it explicitly")
			os.Exit(2)
		}
		bearerToken := strings.TrimSpace(os.Getenv("SCREENCLOUD_MCP_HTTP_TOKEN"))
		if bearerToken == "" {
			fmt.Fprintln(os.Stderr, "refusing MCP HTTP without SCREENCLOUD_MCP_HTTP_TOKEN; use stdio or provide a dedicated bearer secret")
			os.Exit(2)
		}
		streamable := server.NewStreamableHTTPServer(s)
		handler := authenticatedLoopbackHandler(streamable, bearerToken)
		httpSrv := &http.Server{Addr: *addr, Handler: handler, ReadHeaderTimeout: 5 * time.Second}
		fmt.Fprintf(os.Stderr, "screencloud-pp-mcp serving MCP over streamable HTTP at %s\n", *addr)
		if err := httpSrv.ListenAndServe(); err != nil {
			fmt.Fprintf(os.Stderr, "MCP server error: %v\n", err)
			os.Exit(1)
		}
	default:
		fmt.Fprintf(os.Stderr, "unknown --transport %q (supported: stdio, http)\n", *transport)
		os.Exit(2)
	}
}

func authenticatedLoopbackHandler(next http.Handler, bearerToken string) http.Handler {
	expected := []byte("Bearer " + bearerToken)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path != "/mcp" {
			http.NotFound(w, r)
			return
		}
		if !trustedLoopbackAuthority(r.Host) {
			http.Error(w, "untrusted Host", http.StatusMisdirectedRequest)
			return
		}
		if origin := strings.TrimSpace(r.Header.Get("Origin")); origin != "" && !trustedLoopbackOrigin(origin) {
			http.Error(w, "untrusted Origin", http.StatusForbidden)
			return
		}
		provided := []byte(r.Header.Get("Authorization"))
		if len(provided) != len(expected) || subtle.ConstantTimeCompare(provided, expected) != 1 {
			w.Header().Set("WWW-Authenticate", `Bearer realm="screencloud-pp-mcp"`)
			http.Error(w, "unauthorized", http.StatusUnauthorized)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func trustedLoopbackOrigin(raw string) bool {
	parsed, err := url.Parse(raw)
	if err != nil || parsed.Scheme == "" || parsed.Host == "" {
		return false
	}
	return trustedLoopbackAuthority(parsed.Host)
}

func trustedLoopbackAuthority(authority string) bool {
	parsed, err := url.Parse("//" + authority)
	if err != nil {
		return false
	}
	host := strings.TrimSpace(parsed.Hostname())
	if strings.EqualFold(host, "localhost") {
		return true
	}
	ip := net.ParseIP(host)
	return ip != nil && ip.IsLoopback()
}

// defaultTransport reads PP_MCP_TRANSPORT env when set, otherwise falls back
// to "stdio" so running the binary with no args keeps today's behavior.
// Container-hosted agents can pin the transport via env without a flag, which
// matches how hosted-agent process supervisors typically pass configuration.
func defaultTransport() string {
	if t := os.Getenv("PP_MCP_TRANSPORT"); t != "" {
		return t
	}
	return "stdio"
}
